#!/usr/bin/env bash
# Positive controls for native/openssl-check.c: each mutation of native/openssl-min.h must make the
# check fail against OpenSSL 3.6.0's headers (generated by scripts/openssl-headers.sh).  Run from
# the repository root, on a machine with a C compiler (the laptop; the build container has none).
hdr=${1:-.lake/openssl-3.6.0/include}
work=$(mktemp --directory)
cp native/openssl-check.c "$work/"
for mut in \
  's/int SSL_read(SSL \*ssl, void \*buf, int num);/int SSL_read(SSL *ssl, void *buf, size_t num);/' \
  's/#define LH_SSL_CTRL_SET_MIN_PROTO_VERSION 123/#define LH_SSL_CTRL_SET_MIN_PROTO_VERSION 124/' \
  's/#define LH_BIO_C_SET_BUF_MEM_EOF_RETURN 130/#define LH_BIO_C_SET_BUF_MEM_EOF_RETURN 131/' \
  's/typedef struct bio_st BIO;/typedef struct bio_st_x BIO;/' \
  's/long SSL_get_verify_result(const SSL \*ssl);/int SSL_get_verify_result(const SSL *ssl);/' \
  's/uint64_t SSL_CTX_set_options(SSL_CTX \*ctx, uint64_t op);/unsigned long SSL_CTX_set_options(SSL_CTX *ctx, unsigned long op);/'
do
  sed "$mut" native/openssl-min.h > "$work/openssl-min.h"
  if cmp --silent "$work/openssl-min.h" native/openssl-min.h; then echo "did not apply: $mut"; continue; fi
  if cc -std=c11 -Werror -fsyntax-only -I "$hdr" "$work/openssl-check.c" 2> "$work/err.txt"; then
    echo "NOT CAUGHT: $mut"
  else
    echo "caught: $mut"
    grep --max-count=1 error "$work/err.txt" | sed 's/^/    /'
  fi
done
rm --recursive --force "$work"
